pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 newBetLimit, uint256 wagerValue, address player) public {
        // Bound inputs to avoid overflow / unrealistic values
        newBetLimit = bound(newBetLimit, 1, 1e30);
        wagerValue = bound(wagerValue, 1, 1e30);
        vm.assume(player != address(0) && player != address(this));

        // Ensure the contract has some initial balance (e.g., from a previous wager)
        vm.deal(address(c), 1 ether);

        // 1. Open to public
        c.OpenToThePublic();

        // 2. Set new betLimit
        c.AdjustBetAmounts(newBetLimit);

        // 3. Record contract balance before wager
        uint256 balanceBefore = address(c).balance;

        // 4. Attempt wager as player with wagerValue
        vm.deal(player, wagerValue);
        vm.prank(player);
        (bool success, ) = address(c).call{value: wagerValue}(abi.encodeWithSignature("wager()"));

        uint256 balanceAfter = address(c).balance;

        // The rule: if the wager succeeded, then the contract balance increased by exactly wagerValue (if msg.value == betLimit, no refund)
        // If the wager reverted, the balance should be unchanged (the contract should never retain the wager amount when rejecting)
        if (success) {
            // In reference, only allowed when msg.value == betLimit; so balance increases by wagerValue
            assertTrue(balanceAfter == balanceBefore + wagerValue, "Wager should retain full amount");
        } else {
            // If reverted, balance must stay same (no ether taken)
            assertTrue(balanceAfter == balanceBefore, "Reverted wager should not take ether");
        }
    }
}

