pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player, uint256 betLimit1, uint256 betLimit2) public {
        vm.assume(player != address(0) && player != address(this));
        vm.assume(betLimit1 > 0 && betLimit1 <= 1e18);
        vm.assume(betLimit2 > 0 && betLimit2 <= 1e18);

        // Open to public
        c.OpenToThePublic();

        // Set initial bet limit
        c.AdjustBetAmounts(betLimit1);

        // Player wagers exactly betLimit1
        vm.deal(player, betLimit1);
        vm.prank(player);
        c.wager{value: betLimit1}();

        // Change bet limit to betLimit2
        c.AdjustBetAmounts(betLimit2);

        // After AdjustBetAmounts, if player wagered before, their wager equals new betLimit;
        // this holds for reference but not for mutant (mutant allows multiple wagers, so wager may be old value)
        bool hasWagered = c.hasPlayerWagered(player);
        // The rule: hasWagered means wager == betLimit2, else wager == 0
        // But there's no public getter for wagers mapping, so we use hasPlayerWagered and the fact that
        // wager() requires msg.value == betLimit and msg.sender wager == 0 (in reference); after AdjustBetAmounts,
        // if player hasn't wagered again, their wager is still the old value if they hadn't won/lost.
        // Actually the invariant that fails: for reference, after AdjustBetAmounts, a player who wagered before
        // cannot wager again until they play. So their wager remains betLimit1, not betLimit2.
        // The test must check a property that reference satisfies and mutant breaks.
        // Let's use: After AdjustBetAmounts, calling wager with new betLimit for a player who already wagered:
        // - reference reverts (require wagers[msg.sender] == 0 fails)
        // - mutant succeeds (allows multiple wagers)
        vm.deal(player, betLimit2);
        vm.prank(player);
        bool success = address(c).call{value: betLimit2}(abi.encodeWithSignature("wager()"));
        // For reference: success == false (reverts). For mutant: success == true (no revert).
        assertTrue(success == false, "Reference should revert on double wager");
    }
}

