pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betLimitOld, uint256 betLimitNew, address player) public {
        // Ensure bet limits are valid (non-zero for wager to succeed)
        vm.assume(betLimitOld > 0);
        vm.assume(betLimitNew > 0);
        // Ensure player is not the null address and not the contract itself
        vm.assume(player != address(0) && player != address(c));

        // Set up: open to public and set initial bet limit
        c.OpenToThePublic();
        c.AdjustBetAmounts(betLimitOld);

        // Player wagers once
        vm.deal(player, betLimitOld);
        vm.prank(player);
        c.wager{value: betLimitOld}();

        // Record player's wager after initial wager
        bool playerWageredBefore = c.hasPlayerWagered(player);

        // Call AdjustBetAmounts
        c.AdjustBetAmounts(betLimitNew);

        // General rule: if player had wagered before, their wager balance must equal the OLD bet limit
        if (playerWageredBefore) {
            // Since C does not expose individual wager amounts directly, we use the only available getter
            // hasPlayerWagered returns true if wagers[player] > 0, which remains true after AdjustBetAmounts
            // because the mutation only affects the ability to wager multiple times, but the wager amount itself is not reset.
            // However, we need to check the exact amount. Since wagers is private, we cannot read it directly.
            // Instead, we use the fact that the wager amount is stored exactly as sent, and after AdjustBetAmounts,
            // the player's wager amount remains the old bet limit (unchanged). This holds in both P and M.
